    // This method reads a file after validating the input to prevent path traversal attacks.
    public static void readFile(String userInput) throws IOException {
        // Validate the user input to ensure it does not contain path traversal sequences.
        if (!Pattern.matches("^[a-zA-Z0-9_\\-]+\\.txt$", userInput)) {
            throw new IllegalArgumentException("Invalid filename format");
        }

        // Use a known safe base directory and resolve the user input against it.
        Path baseDir = Paths.get("safe_directory");
        Path resolvedPath = baseDir.resolve(userInput).normalize();

        // Check if the resolved path is still within the base directory.
        if (!resolvedPath.startsWith(baseDir)) {
            throw new SecurityException("Attempt to access files outside the allowed directory");
        }

        BufferedReader reader = new BufferedReader(new FileReader(resolvedPath.toFile()));
        String line;
        while ((line = reader.readLine()) != null) {
            System.out.println(line);
        }
        reader.close();
    }

    public static void main(String[] args) throws IOException {
        // Example input that is now safely processed.
        String userInput = "example.txt";
        readFile(userInput);
    }
